using System.Linq;using UnityEngine;using UnityEngine.EventSystems;using DeadSurvivor;public static class DragInspect {public static object Run(){var g=Object.FindAnyObjectByType<DSGame>();var i=g.Stash.Last(i=>i.type=="heal");var target=Object.FindObjectsByType<DSPointer>().First(p=>p.character==0&&p.x==4&&p.y==4&&p.gameObject.activeInHierarchy);var r=(RectTransform)target.transform;var pos=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center));var e=new PointerEventData(EventSystem.current){position=pos};var hits=new System.Collections.Generic.List<RaycastResult>();EventSystem.current.RaycastAll(e,hits);return new {pos,screen=new Vector2(Screen.width,Screen.height),can=g.CanPlace(i,g.Team[0],4,4),hits=string.Join(",",hits.Select(h=>h.gameObject.name)),raycasters=Object.FindObjectsByType<UnityEngine.UI.GraphicRaycaster>().Length,active=target.gameObject.activeInHierarchy};}}
